def run(value_list):
    """
    Calculates the change in the amount for Appliances in 2019 from 2018.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the change in amount and the scale.
    """

    appliances_2019 = None
    appliances_2018 = None

    for item in value_list:
        if item['category'] == 'Appliances and item['header3'] == '2019':
            appliances_2019 = item['number_value']
        if item['category'] == 'Appliances' and item['header3'] == '2018':
            appliances_2018 = item['number_value']

    if appliances_2019 is not None and appliances_2018 is not None:
        change = appliances_2019 - appliances_2018
        return (round(change, 2), 'million')
    else:
        return (0.0, '')

