def run(value_list):
    """
    Calculates the average difference between EBIDTA and underlying EBIDTA for both FYs.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the calculated difference (float with two decimal places) and its scale (string).
    """

    ebitda_2019 = None
    underlying_ebitda_2019 = None
    ebitda_2018 = None
    underlying_ebitda_2018 = None

    for item in value_list:
        if item['category'] == 'EBIDTA' and item['header2'] == '30 June 2019':
            ebitda_2019 = item['number_value']
        elif item['category'] == 'Underlying EBIDTA' and item['header2'] == '30 June 2019':
            underlying_ebitda_2019 = item['number_value']
        elif item['category'] == 'EBIDTA' and item['header2'] == '30 June 2018':
            ebitda_2018 = item['number_value']
        elif item['category'] == 'Underlying EBIDTA' and item['header2'] == '30 June 2018':
            underlying_ebitda_2018 = item['number_value']

    if ebitda_2019 is not None and underlying_ebitda_2019 is not None and ebitda_2018 is not None and underlying_ebitda_2018 is not None:
        difference_2019 = ebitda_2019 - underlying_ebitda_2019
        difference_2018 = ebitda_2018 - underlying_ebitda_2018
        average_difference = (difference_2019 + difference_2018) / 2
        return (float(average_difference), 'thoousand')
    else:
        return (0.0, '')

