def run(value_list):
    """
    Calculates the average dividend yield for the years 2017, 2018, and 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary contains
            information about a financial value.

    Returns:
        A tuple containing the average dividend yield and its scale.
    """

    dividend_yields = []
    for item in value_list:
        if item['category'] == 'Dividend yield':
            dividend_yields.append(item['number_value'])

    if len(dividend_yields) < 3:
        return (0.0, '')

    years = [2017, 2018, 2019]
    total_yield = 0.0
    for i in range(len(years)):
        year = years[i]
        for item in value_list:
            if item['category'] == 'Dividend yield' and item['header1'] == str(year):
                total_yield += item['number_value']
                break

    average_yield = total_yield / 3.0
    return (round(average_yield, 2), '%')

def run(value_list):
    """
    Calculates the increase/decrease in cost from 2018 to 2019.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the numeric value and its scale.
    """

    cost_2018 = None
    cost_2019 = None

    for item in value_list:
        if item['header1'] == '2018' and item['category'] == 'Cost':
            cost_2018 = item['number_value']
        elif item['header1'] == '2019' and item['category'] == 'Cost':
            cost_2019 = item['number_value']

    if cost_2018 is not None and cost_2019 is not None:
        increase_decrease = cost_2019 - cost_2018
        if increase_decrease > 0:
            scale = "million"
        elif increase_decrease < 0:
            scale = "million"
        else:
            scale = ""
        return (round(increase_decrease, 2), scale)
    else:
        return (0.0, "")

def run(value_list):
    """
    Calculates the average Selling, general and administrative cost for the given years.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple containing the average cost and its scale.
    """
    selling_general_administrative_costs = []
    for item in value_list:
        if item['category'] == 'Selling, general and administrative':
            selling_general_administrative_costs.append(item['number_value'])

    if len(selling_general_administrative_costs) < 2:
        return (0.0, 'million')

    if 2019 in [item['header1'] for item in value_list if item['category'] == 'Selling, general and administrative']:
        cost_2019 = next((item['number_value'] for item in value_list if item['category'] == 'Selling, general and administrative' and item['header1'] == '2019'), 0)
        cost_2018 = next((item['number_value'] for item in value_list if item['category'] == 'Selling, general and administrative' and item['header1'] == '2018'), 0)
        average_cost = (cost_2019 + cost_2018) / 2
        return (round(average_cost, 2), 'million')
    elif 2018 in [item['header1'] for item in value_list if item['category'] == 'Selling, general and administrative']:
        cost_2018 = next((item['number_value'] for item in value_list if item['category'] == 'Selling, general and administrative' and item['header1'] == '2018'), 0)
        cost_2017 = next((item['number_value'] for item in value_list if item['category'] == 'Selling, general and administrative' and item['header1'] == '2017'), 0)
        average_cost = (cost_2018 + cost_2017) / 2
        return (round(average_cost, 2), 'million')
    elif 2017 in [item['header1'] for item in value_list if item['category'] == 'Selling, general and administrative']:
        cost_2017 = next((item['number_value'] for item in value_list if item['category'] == 'Selling, general and administrative' and item['header1'] == '2017'), 0)
        cost_2016 = next((item['number_value'] for item in value_list if item['category'] == 'Selling, general and administrative' and item['header1'] == '2016'), 0)
        average_cost = (cost_2017 + cost_2016) / 2
        return (round(average_cost, 2), 'million')
    else:
        return (0.0, 'million')

