def run(value_list):
    operating_income_values = []
    for item in value_list:
        if item['category'] == 'Operating income':
            operating_income_values.append(item['value'])

    if not operating_income_values:
        return (0.0, '')

    total_income = sum(operating_income_values)
    num_years = len(operating_income_values)

    if num_years == 1:
        return (round(total_income, 2), 'million')

    average_income = total_income / num_years
    return (round(average_income, 2), 'million')

