def run(value_list):
    """
    Calculates the average Tax exempt interest income from the provided value list.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple containing the average tax exempt interest income and its scale.
    """

    interest_income = []
    for item in value_list:
        if item['category'] == 'Tax exempt interest income':
            interest_income.append(item['number_value'])

    if not interest_income:
        return (0.0, '')

    if len(interest_income) == 1:
        return (float(interest_income[0]), '')

    if len(interest_income) == 2:
        return ( (interest_income[0] + interest_income[1]) / 2, '')


    return (float(sum(interest_income)) / len(interest_income), '')

