def run(value_list):
    """
    Calculates the average annual operating leases contractual obligations for 2020-2024.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the calculated average value and its scale.
    """

    operating_leases_data = [item for item in value_list if item['category'] == 'Opereating leases (1)']

    values = []
    for item in operating_leases_data:
        if item['header1'] == '2020':
            values.append(item['number_value'])
        elif item['header1'] == '2021-2022':
            values.append(item['number_value'])
        elif item['header1'] == '2023-2024':
            values.append(item['number_value'])
        elif item['header1'] == 'Thereafter':
            values.append(item['number_value'])

    if not values:
        return (0.0, "")

    total = sum(values)
    num_years = len(values)

    if num_years == 1:
        return (total, values[0]['scale'])

    average = total / num_years
    return (round(average, 2), values[0]['scale'])

