def run(value_list):
    """

    Calculates the difference between the average salaries and fees and the average incentive schemes from 2018 to 2019.

    Args:
        value_list (list): A list of dictionaries, where each dictionary contains the number value, scale, category, and header1.

    Returns:
        tuple: A tuple containing the calculated difference as a float with two decimal places and the scale.
    """

    salaries_and_fees_2019 = None
    salaries_and_fees_2018 = None
    incentive_schemes_2019 = None
    incentive_schemes_2018 = None

    for item in value_list:
        if item['category'] == 'Salaries and fees' and item['header1'] == '2019 € million':
            salaries_and_fees_2019 = item['number_value']
        elif item['category'] == 'Salaries and fees' and item['header1'] == '2018 € million':
            salaries_and_fees_2018 = item['number_value']
        elif item['category'] == 'Incentive schemes1' and item['header1'] == '2019 € million':
            incentive_schemes_2019 = item['number_value']
        elif item['category'] == 'Incentive schemes1' and item['header1'] == '2018 € million':
            incentive_schemes_2018 = item['number_value']

    if salaries_and_fees_2019 is not None and salaries_and_fees_2018 is not None and incentive_schemes_2019 is not None and incentive_schemes_2018 is not None:
        avg_salaries_fees = (salaries_and_fees_2019 + salaries_and_fees_2018) / 2
        avg_incentive_schemes = (incentive_schemes_2019 + incentive_schemes_2018) / 2
        difference = avg_salaries_fees - avg_incentive_schemes
