def run(value_list):
    research_and_dev_funding = []
    for item in value_list:
        if item['category'] == 'Research and development funding':
            research_and_dev_funding.append(item['number_value'])

    if len(research_and_dev_funding) < 2:
        return (round(sum(research_and_dev_funding) / len(research_and_dev_funding), 2), 'million')

    years = []
    values = []
    for item in research_and_dev_funding:
        years.append(item['header2'])
        values.append(item['number_value'])

    years = sorted(list(set(years)))

    if len(years) < 2:
        return (round(sum(values) / len(values), 2), 'million')

    total_sum = 0
    for i in range(len(years) - 1):
        total_sum += values[i] + values[i+1]

    average = total_sum / (len(years) - 1)

    return (round(average, 2), 'million')

def run(value_list):
    """
    Calculates the average gain on sale of businesses and non-current assets.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

