    """
    gain_on_sale_values = [v['number_value'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets']

    if len(gain_on_sale_values) < 2:
        return (0.0, 'million')

    if 2019 in [v['header2'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets']:
        gain_2019 = next((v['number_value'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets' and v['header2'] == '2019'), 0)
        if 2018 in [v['header2'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets']:
            gain_2018 = next((v['number_value'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets' and v['header2'] == '2018'), 0)
            average_gain = (gain_2019 + gain_2018) / 2
            return (round(average_gain, 2), 'million')
        else:
            return (round(gain_2019, 2), 'million')
    elif 2018 in [v['header2'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets']:
        gain_2018 = next((v['number_value'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets' and v['header2'] == '2018'), 0)
        if 2017 in [v['header2'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets']:
            gain_2017 = next((v['number_value'] for v in value_list if v['category'] == 'Gain on sale of businesses and non-current assets' and v['header2'] == '2017'), 0)
            average_gain = (gain_2018 + gain_2017) / 2
            return (round(average_gain, 2), 'million')
        else:
            return (round(gain_2018, 2), 'million')
    else:
        return (round(gain_on_sale_values[0], 2), 'million')

