def run(value_list):
    """
    Calculates the difference in total expected charges between Transportaation Solutions and Industrial Solutions.

    Args:
        value_list: A list of dictionaries, where each dictionary contains financial data.

    Returns:
        A tuple containing the difference in total expected charges and the scale.
    """

    transportation_solutions_total = 0
    industrial_solutions_total = 0

    for item in value_list:
        if item['category'] == 'Transportaation Solutions' and item['header2'] == 'Total Expected Charges':
            transportation_solutions_total = float(item['number_value'])
        if item['category'] == 'Industrial Solutions' and item['header2'] == 'Total Expected Charges':
            industrial_solutions_total = float(item['number_value'])

    difference = transportation_solutions_total - industrial_solutions_total

    if difference == 0:
        scale = ""
    elif difference < 1000000:
        scale = "million"
    elif difference < 1000000000:
        scale = "billion"
    else:
        scale = "trillion"

    return (round(difference, 2), scale)

def run(value_list):
    """
    Calculates the average amount of total expected charges per segment.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a value with its attributes.

    Returns:
        A tuple containing the average total expected charges and the scale.
    """

    segment_totals = {}
    for item in value_list:
        category = item['category']
        if category not in segment_totals:
            segment_totals[category] = 0
        segment_totals[category] += item['number_value']

    num_segments = len(segment_totals)

    if num_segments == 0:
        return (0.0, "")

    total_expected_charges = sum(segment_totals.values())
    average_expected_charges = total_expected_charges / num_segments

    return (round(average_expected_charges, 2), "million")

