def run(value_list):
    """
    Calculates the average unvested restricted stock from the given value list.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a value.

    Returns:
        A tuple containing the average unvested restricted stock and its scale.
    """
    unvested_restricted_stock_values = []
    for item in value_list:
        if item['category'] == 'Unvested restricted stock':
            unvested_restricted_stock_values.append(item['number_value'])

    if not unvested_restricted_stock_values:
        return (0.0, '')

    if len(unvested_restricted_stock_values) == 1:
        return (round(unvested_restricted_stock_values[0], 2), '')

    # Calculate the year average
    years = sorted(list(set([item['header1'] for item in value_list if item['category'] == 'Unvested restricted stock'])))
    if len(years) < 2:
        return (round(sum(unvested_restricted_stock_values) / len(unvested_restricted_stock_values), 2), '')

    total_average = 0
    for i in range(len(years) - 1):
        year1 = years[i]
        year2 = years[i+1]
        value1 = next((item['number_value'] for item in value_list if item['header1'] == year1 and item['category'] == 'Unvested restricted stock'), 0)
        value2 = next((item['number_value'] for item in value_list if item['header1'] == year2 and item['category'] == 'Unvested restricted stock'), 0)
        total_average += (value1 + value2) / 2

    average_value = total_average / (len(years) - 1)
    return (round(average_value, 2), '')

