def run(value_list):
    oem_values = []
    for item in value_list:
        if item['category'] == 'OEM':
            oem_values.append(item['number_value'])

    if len(oem_values) < 2:
        return (round(sum(oem_values) / len(oem_values), 2), 'percent')

    oem_values.sort()

    if len(oem_values) == 2:
        average = (oem_values[0] + oem_values[1]) / 2
    else:
        average = (oem_values[0] + oem_values[-1]) / 2

    return (round(average, 2), 'percent')

