def run(value_list):
    cost_of_sales_values = []
    for item in value_list:
        if item['category'] == 'Cost of sales':
            cost_of_sales_values.append(item['number_value'])

    if len(cost_of_sales_values) < 2:
        return (0.0, 'million')

    total_cost = sum(cost_of_sales_values)

    years = []
    for item in value_list:
        if item['category'] == 'Cost of sales':
            years.append(item['header2'])

    unique_years = sorted(list(set(years)))

    if len(unique_years) < 2:
        return (0.0, 'million')


    total_sum = 0.0
    for year in unique_years:
        for item in value_list:
            if item['category'] == 'Cost of sales' and item['header2'] == year:
                total_sum += item['number_value']

    average_cost = total_sum / len(unique_years)

    return (round(average_cost, 2), 'million')

def run(value_list):
    gross_margin_values = []
    for item in value_list:
        if item['category'] == 'Gross margin (as percentage of net revenues'):
            gross_margin_values.append(item['number_value'])

    if len(gross_margin_values) < 2:
        return (0.0, '')

    years = []
    values = []
    for item in value_list:
        if item['category'] == 'Gross margin (as percentage of net revenues)':
            years_str = item['header2']
            year = int(years_str.split(' ')[-1])
            values.append(item['number_value'])
            years.append(year)

    if len(years) < 2:
        return (0.0, '')

    year_values = {}
    for i in range(len(years)):
        year = years[i]
        year_values[year] = values[i]

    total_sum = 0.0
    for year in sorted(year_values.keys()):
        total_sum += year_values[year]

    average_gross_margin = total_sum / len(years)

    return (round(average_gross_margin, 2), 'million')

