    """
    Calculates the average investment income between 2018 and 2019.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the average investment income and its scale.
    """
    investment_income_2019 = 0
    investment_income_2018 = 0

    for item in value_list:
        if item['category'] == 'Investment income' and item['header2'] == '2019':
            investment_income_2019 = item['number_value']
        elif item['category'] == 'Investment income' and item['header2'] == '2018':
            investment_income_2018 = item['number_value']

    if investment_income_2018 == 0 and investment_income_2019 == 0:
        return (0.0, '')

    average_income = (investment_income_2018 + investment_income_2019) / 2
    return (round(average_income, 2), '')

def run(value_list):
    """
    Calculates the average financing costs between 2018 and 2019.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the average financing costs and the scale.
    """
    financing_costs_2018 = 0
    financing_costs_2019 = 0

    for item in value_list:
        if item['header2'] == '2018' and item['category'] == 'Financing costs':
            financing_costs_2018 = item['number_value']
        elif item['header2'] == '2019' and item['category'] == 'Financing costs':
            financing_costs_2019 = item['number_value']

    if financing_costs_2018 == 0 or financing_costs_2019 == 0:
        return (0.0, '')

    average_financing_costs = (financing_costs_2018 + financing_costs_2019) / 2
    return (round(average_financing_costs, 2), '')

def run(value_list):
    """
    Calculates the difference between the average investment income and average financing costs.

    Args:
        value_list: A list of dictionaries, where each dictionary contains financial data.

    Returns:
        A tuple containing the calculated difference (float with two decimal places) and the scale (string).
    """

    investment_income_values = []
    financing_costs_values = []

    for item in value_list:
        if item['category'] == 'Investment income':
            investment_income_values.append(item['number_value'])
        elif item['category'] == 'Financing costs' or item['category'] == 'Net financing costs':
            financing_costs_values.append(item['number_value'])

    if not investment_income_values or not financing_costs_values:
        return (0.0, '')

    if len(investment_income_values) > 1 and len(financing_costs_values) > 1:
        investment_income_2019 = next((item['number_value'] for item in investment_income_values if item['header2'] == '2019'), 0)
        investment_income_2018 = next((item['number_value'] for item in investment_income_values if item['header2'] == '2018'), 0)

        financing_costs_2019 = next((item['number_value'] for item in financing_costs_values if item['header2'] == '2019'), 0)
        financing_costs_2018 = next((item['number_value'] for item in financing_costs_values if item['header2'] == '2018'), 0)

        avg_investment_income = (investment_income_2019 + investment_income_2018) / 2
        avg_financing_costs = (financing_costs_2019 + financing_costs_2018) / 2

        difference = avg_investment_income - avg_financing_costs
        return (round(difference, 2), 'million')
    else:
        return (0.0, '')

