def run(value_list):
    """
    Calculates the change in additions of financial assets from 2018 to 2019.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the change in additions and the scale.
    """

    additions_2018 = 0
    additions_2019 = 0

    for item in value_list:
        if item['category'] == 'Additions' and item['header2'] == '2018':
            additions_2018 = item['number_value']
        elif item['category'] == 'Additions' and item['header2'] == '2019':
            additions_2019 = item['number_value']

    change = additions_2019 - additions_2018

    if change == 0:
        scale = ""
    elif change < 1000000:
        scale = "million"
    elif change < 1000000000:
        scale = "billion"
    else:
        scale = "trillion"

    return (float(change), scale)

