def run(value_list):
    gross_margin_values = [item for item in value_list if "GAAP-based Professional Service and Other Gross Margin %" in item]

    if not gross_margin_values:
        return (0.0, "")

    values = [float(item.split(":")[1].strip()) for item in gross_margin_values]

    if len(values) < 2:
        return (0.0, "")

    total_margin = sum(values)

    if len(values) == 2:
        average_margin = total_margin / 2
    else:
        # Calculate the average of the last two years
        average_margin = (values[-1] + values[-2]) / 2

    return (round(average_margin, 2), "percent")

def run(value_list):
    gross_profit_values = [item for item in value_list if "GAAP-based Professional Service and Other Gross Profi" in item]

    if len(gross_profit_values) < 2:
        return (0.0, "")

    years = []
    values = []
    for item in gross_profit_values:
        try:
            year = int(item.split(" ")[-2])
            value = float(item.split(" ")[-1].replace(",", ""))
            years.append(year)
            values.append(value)
        except:
            continue

    years = sorted(list(set(years)))

    if len(years) < 2:
        return (0.0, "")

    averages = []
    for i in range(1, len(years)):
        prev_year = years[i-1]
        current_year = years[i]
        averages.append((values[i-1] + values[i]) / 2)

    average_gross_profit = sum(averages) / len(averages)
    return (round(average_gross_profit, 2), "thousand")

def run(value_list):
    """
    Calculates the percentage increase of GAAP-based Professional Service and Other Gross Profit
    from fiscal year 2017 to 2019.

    Args:
        value_list (list): A list of annotated values.

    Returns:
        tuple: A tuple containing the calculated number (float with two decimal places) and the scale (string).
    """
    try:
        profit_2017 = None
        profit_2019 = None

        for item in value_list:
            if "GAAP-based Professional Service and Other Gross Profi" in item['category'] and item['header2'] == '2017':
                profit_2017 = item['number']
            if "GAAP-based Professional Service and Other Gross Profi" in item['category'] and item['header2'] == '2019':
                profit_2019 = item['number']

        if profit_2017 is not None and profit_2019 is not None:
            increase = ((profit_2019 - profit_2017) / profit_2017) * 100
            return (round(increase, 2), "percent")
        else:
            return (None, "")

    except Exception as e:
        return (None, "")

def run(value_list):
    """
    Calculates the proportion of long-term debt payments due in 5 years or below.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the number and scale of the calculated proportion, 
        formatted to two decimal places.
    """
    total_long_term_debt_5_years_below = 0
    total_long_term_debt = 0

    for item in value_list:
        if "Long-term debt ." in item["category"]:
            if item["header2"] == "Payments Due by Period (in millions)":
                if item["header1"] == "After 5 Years":
                    total_long_term_debt += item["number_value"]
                elif item["header1"] == "3-5 Years":
                    total_long_term_debt += item["number_value"]
                elif item["header1"] == "1-3 Years":
                    total_long_term_debt += item["number_value"]
                elif item["header1"] == "Total":
                    total_long_term_debt += item["number_value"]

    if total_long_term_debt == 0:
        return (0.00, "")

    proportion = total_long_term_debt / total_long_term_debt_5_years_below
    return (round(proportion, 2), "million")

def run(value_list):
    """
    Calculates the ratio of total notes payable to total capital lease obligations.

    Args:
        value_list: A list of dictionaries containing financial data.

    Returns:
        A tuple containing the calculated ratio as a float (rounded to two decimal places)
        and the scale of the value (e.g., "million").
    """

    notes_payable_total = 0
    capital_lease_total = 0

    for item in value_list:
        if item['category'] == 'Notes payable' and item['header1'] == 'Total':
            notes_payable_total = item['number_value']
        elif item['category'] == 'Capital lease obligations' and item['header1'] == 'Total':
            capital_lease_total = item['number_value']

    if capital_lease_total == 0:
        return (0.00, "million")  # Avoid division by zero

    ratio = (notes_payable_total / capital_lease_total) * 100
    return (round(ratio, 2), "percent")

