    Calculates the average State licenses value for the given year.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a value with its attributes.

    Returns:
        A tuple containing the average State licenses value and the scale.
    """
    state_licenses_values = [value for value in value_list if value['category'] == 'State licenses']

    if not state_licenses_values:
        return (0.0, '')

    values = [float(value['number_value']) for value in state_licenses_values]

    if len(values) == 1:
        return (round(values[0], 2), '')

    if len(values) == 2:
        year1 = value_list[0]['header1']
        year2 = value_list[1]['header1']
        value1 = value_list[0]['number_value']
        value2 = value_list[1]['number_value']
        return (round((value1 + value2) / 2, 2), '')


    return (round(sum(values) / len(values), 2), '')

def run(value_list):
    """
    Calculates the percentage increase/decrease in the total from 2018 to 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a value
                    with keys 'number_value', 'scale', 'category', 'header1', and 'header2'.

    Returns:
        A tuple containing the calculated percentage (float with two decimal places) and the scale (empty string).
    """

    total_2019 = 0
    total_2018 = 0

    for item in value_list:
        if item['header1'] == '2019' and item['category'] == 'Total':
            total_2019 = item['number_value']
        elif item['header1'] == '2018' and item['category'] == 'Total':
            total_2018 = item['number_value']

    if total_2018 == 0:
        percentage_change = 0.00
        scale = ""
    else:
        percentage_change = ((total_2019 - total_2018) / total_2018) * 100
        scale = "%"

    return (round(percentage_change, 2), scale)

def run(value_list):
    """
    Calculates the percentage change in total personnel expenses from 2018 to 2019.

    Args:
        value_list: A list of dictionaries, where each dictionary represents a financial value.

    Returns:
        A tuple containing the percentage change as a float (rounded to two decimal places) and the scale.
    """

    total_2018 = 0
    total_2019 = 0

    for item in value_list:
        if item['header1'] == '2018' and item['category'] == 'Total':
            total_2018 = item['number_value']
        elif item['header1'] == '2019' and item['category'] == 'Total':
            total_2019 = item['number_value']

    if total_2018 == 0:
        return (0.0, '')

    percentage_change = ((total_2019 - total_2018) / total_2018) * 100

    return (round(percentage_change, 2), '')

def run(value_list):
