def run(value_list):
    """
    Calculates the average telecommunications installation from the given value list.

    Args:
        value_list: A list of dictionaries, where each dictionary contains
                    information about a financial value.

    Returns:
        A tuple containing the average telecommunications installation value and its scale.
    """
    installation_values = [v['number_value'] for v in value_list if v['category'] == 'Telecommunication - Installation']

    if len(installation_values) < 2:
        return (0.0, '')

    if 2019 in [v['header1'] for v in value_list] and 2018 in [v['header1'] for v in value_list]:
        installation_2019 = next((v['number_value'] for v in value_list if v['category'] == 'Telecommunication - Installation' and v['header1'] == '2019'), 0)
        installation_2018 = next((v['number_value'] for v in value_list if v['category'] == 'Telecommunication - Installation' and v['header1'] == '2018'), 0)
        average_installation = (installation_2019 + installation_2018) / 2
        return (float(average_installation), '')
    else:
        return (0.0, '')

